/**
 * Invite code system (PRD §A4: 邀请制免费).
 *
 * Phase A is invite-only free. Codes are generated by admins, single-use,
 * consumed on registration. Stored in the Setting table under `invite.<code>`.
 */

import { prisma } from '@/lib/prisma';
import { logger } from '@/lib/logger';
import { nanoid } from 'nanoid';

/** Generate a single invite code (admin action). */
export async function generateInviteCode(): Promise<string> {
  const code = `NSP-${nanoid(8).toUpperCase()}`;
  await prisma.setting.create({
    data: { key: `invite.${code}`, value: 'unused' },
  });
  logger.info('Invite code generated', { code });
  return code;
}

/** Generate N invite codes at once (bulk admin action). */
export async function generateInviteCodes(count: number): Promise<string[]> {
  const codes: string[] = [];
  for (let i = 0; i < Math.min(count, 100); i++) {
    codes.push(await generateInviteCode());
  }
  return codes;
}

/** Validate + consume an invite code (called on registration). Returns true if valid. */
export async function consumeInviteCode(code: string): Promise<boolean> {
  const key = `invite.${code}`;
  const row = await prisma.setting.findUnique({ where: { key } });
  if (!row || row.value !== 'unused') {
    return false;
  }
  await prisma.setting.update({ where: { key }, data: { value: 'consumed' } });
  logger.info('Invite code consumed', { code });
  return true;
}

/** Check if an invite code is valid (without consuming). */
export async function isValidInviteCode(code: string): Promise<boolean> {
  const row = await prisma.setting.findUnique({ where: { key: `invite.${code}` } });
  return row?.value === 'unused';
}
